    {
      "name": "index.ts",
      "content": "import 'jsr:@supabase/functions-js/edge-runtime.d.ts'

const jsonHeaders = { 'Content-Type': 'application/json' }

function json(body: unknown, status = 200, headers: HeadersInit = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...jsonHeaders, ...headers },
  })
}

function badRequest(error: string) {
  return json({ error }, 400)
}

Deno.serve(async (req) => {
  if (req.method !== 'POST') {
    return json({ error: 'Method not allowed' }, 405, { Allow: 'POST' })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return badRequest('Invalid JSON body')
  }

  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return badRequest('Body must be a JSON object with a non-empty items array')
  }

  const { items, customer_tier, coupon } = body as Record<string, unknown>
  if (!Array.isArray(items) || items.length === 0) {
    return badRequest('items must be a non-empty array')
  }

  let subtotal_cents = 0
  for (const item of items) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      return badRequest('Each item must be an object with positive unit_price_cents and quantity')
    }

    const { unit_price_cents, quantity } = item as Record<string, unknown>
    if (
      typeof unit_price_cents !== 'number' ||
      typeof quantity !== 'number' ||
      !Number.isSafeInteger(unit_price_cents) ||
      !Number.isSafeInteger(quantity) ||
      unit_price_cents <= 0 ||
      quantity <= 0
    ) {
