    if (!Number.isSafeInteger(lineTotal) || !Number.isSafeInteger(subtotal_cents + lineTotal)) {
      return badRequest('Order total is too large')
    }
    subtotal_cents += lineTotal
  }

  const couponDiscount = coupon === 'WELCOME10'
    ? Math.min(Math.round(subtotal_cents * 0.10), 2000)
    : 0
  const enterpriseDiscount = customer_tier === 'enterprise'
    ? Math.round(subtotal_cents * 0.15)
    : 0
  const discount_cents = Math.max(couponDiscount, enterpriseDiscount)
  const postDiscount_cents = subtotal_cents - discount_cents
  const tax_cents = Math.round(postDiscount_cents * 0.0725)
  const total_cents = postDiscount_cents + tax_cents

